import dspy
from dspy.utils.dummies import DummyLM


class FlakyStructuredDummyLM(DummyLM):
    def __init__(self, answers):
        super().__init__(answers, adapter=dspy.JSONAdapter())
        self.seen_formats = []

    @property
    def supported_params(self):
        return {'response_format'}

    @property
    def supports_response_schema(self):
        return True

    def forward(self, prompt=None, messages=None, **kwargs):
        self.seen_formats.append(kwargs.get('response_format'))
        if len(self.seen_formats) == 1 and isinstance(kwargs.get('response_format'), type):
            raise RuntimeError('structured output failed')
        return super().forward(prompt=prompt, messages=messages, **kwargs)


class Sig(dspy.Signature):
    question: str = dspy.InputField()
    answer: str = dspy.OutputField()


lm = FlakyStructuredDummyLM([{'answer': 'Paris'}])
dspy.configure(lm=lm, adapter=dspy.JSONAdapter())

pred = dspy.Predict(Sig)(question='What is the capital of France?')
assert pred.answer == 'Paris'
assert len(lm.seen_formats) == 2
assert isinstance(lm.seen_formats[0], type)
assert lm.seen_formats[1] == {'type': 'json_object'}

print(lm.seen_formats)
