from types import SimpleNamespace

import dspy


class NativeToolCallLM(dspy.BaseLM):
    def __init__(self):
        super().__init__('native-tool-call')

    @property
    def supports_function_calling(self):
        return True

    def forward(self, prompt=None, messages=None, **kwargs):
        return SimpleNamespace(
            choices=[
                SimpleNamespace(
                    message=SimpleNamespace(
                        content=None,
                        tool_calls=[{'function': {'name': 'get_weather', 'arguments': '{"city": "Paris"}'}}],
                    ),
                    finish_reason='tool_calls',
                )
            ],
            usage={'prompt_tokens': 0, 'completion_tokens': 0, 'total_tokens': 0},
            model='native-tool-call',
        )


def get_weather(city: str) -> str:
    return f'Sunny in {city}'


class ToolCallSig(dspy.Signature):
    question: str = dspy.InputField()
    tools: list[dspy.Tool] = dspy.InputField()
    answer: str = dspy.OutputField()
    tool_calls: dspy.ToolCalls = dspy.OutputField()


adapter = dspy.JSONAdapter(use_native_function_calling=True)
lm = NativeToolCallLM()
result = adapter(lm, {}, ToolCallSig, [], {'question': 'Weather in Paris?', 'tools': [dspy.Tool(get_weather)]})[0]

assert result['answer'] is None
assert result['tool_calls'] == dspy.ToolCalls(
    tool_calls=[dspy.ToolCalls.ToolCall(name='get_weather', args={'city': 'Paris'})]
)

print(result)
